/**
 * seed.sql
 * 
 * Comprehensive seed data for VenU MVP testing.
 * Creates 60+ providers across 3 campuses with services and availability.
 * 
 * WARNING: This seed creates FAKE test users. It will delete ALL test data
 * (venues, services, bookings, availability) but PRESERVES real user accounts.
 * 
 * Data includes:
 * - 3 Campuses: State University, Ivy College, Tech Institute
 * - ~20 Providers per campus with venues and services
 * - 5-7 Food & Drinks providers per campus
 * - Weekly availability schedules for all venues
 * - All venues set to 'approved' status for testing
 * - All cover images are accurate representations of the service/venue
 * 
 * IMPORTANT: Real user accounts are NOT deleted. The seed only deletes:
 * - Test users (emails ending in @state.edu, @ivy.edu, @tech.edu)
 * - All venues, services, bookings, reviews, and availability
 * 
 * To add protected admin emails, set NEXT_PUBLIC_ADMIN_EMAILS in your .env.local:
 * NEXT_PUBLIC_ADMIN_EMAILS=your@email.com,buddy@email.com
 */

DO $$
DECLARE
    new_user_id UUID;
    new_venue_id UUID;
    
    campus_data JSONB;
    provider_json JSONB;
    service_json JSONB;
    day_num INTEGER;
    
    -- Provider Data with Categories and Accurate Images
    providers_data JSONB := '[
        {
            "campus": "State University",
            "providers": [
                {"name": "Mike The Barber", "email": "mike@state.edu", "phone": "(555) 234-5678", "avatar": "https://images.unsplash.com/photo-1599566150163-29194dcaad36?w=200&auto=format&fit=crop&q=60", "venue": "Mike''s Fresh Fades", "description": "Sharpest cuts on campus. Located in Dorm A.", "cover": "https://images.unsplash.com/photo-1585747860715-2ba37e788b70?w=800&auto=format&fit=crop&q=60", "category": "Beauty", "bio": "Hey, I''m Mike! I''m 24 years old and originally from Chicago. I''ve been cutting hair since I was 16, starting at my uncle''s barbershop back home. I''m currently a junior studying Business Administration here at State University, but barbering is my true passion. I love creating fresh looks and helping people feel confident. When I''m not cutting hair or studying, you''ll find me playing basketball at the rec center, watching the Bulls play, or trying out new barber techniques. My favorite movies are The Godfather and Training Day. I''m a huge hip-hop fan and love discovering new artists. I started this business to help students look sharp without breaking the bank. Come through for a cut and let''s talk about life, music, or whatever''s on your mind!", "services": [{"name": "Fresh Fade", "desc": "Skin fade with lineup", "duration": 45, "price": 25}, {"name": "Buzz Cut", "desc": "One length all over", "duration": 30, "price": 15}, {"name": "Beard Trim", "desc": "Shape and trim", "duration": 20, "price": 10}, {"name": "Full Service", "desc": "Haircut + beard", "duration": 60, "price": 35}]},
                {"name": "Emma Wilson", "email": "emma@state.edu", "phone": "(555) 234-5679", "avatar": "https://images.unsplash.com/photo-1534528741775-53994a69daeb?w=200&auto=format&fit=crop&q=60", "venue": "Emma''s Nail Studio", "description": "Gel nails, acrylics, and nail art.", "cover": "https://images.unsplash.com/photo-1604654894610-df63bc536371?w=800&auto=format&fit=crop&q=60", "category": "Beauty", "bio": "Hi! I''m Emma, 22 years old and a senior majoring in Art & Design. I''m from Los Angeles originally, but I''ve fallen in love with campus life here. I''ve been doing nails since high school when I started doing my friends'' nails for fun. Now I''m certified and love creating beautiful nail art! When I''m not doing nails, I''m usually painting, watching art tutorials on YouTube, or exploring local coffee shops. My favorite movies are La La Land and The Grand Budapest Hotel. I''m obsessed with indie music and love going to concerts. I also enjoy yoga and meditation to keep myself balanced. My goal is to help everyone feel beautiful and confident through their nails. I specialize in custom designs and love when clients bring in inspiration photos!", "services": [{"name": "Gel Manicure", "desc": "Full gel set", "duration": 60, "price": 35}, {"name": "Acrylic Full Set", "desc": "Acrylic extensions", "duration": 90, "price": 50}, {"name": "Nail Art", "desc": "Custom designs", "duration": 45, "price": 25}, {"name": "Pedicure", "desc": "Relaxing pedicure", "duration": 60, "price": 40}]},
                {"name": "Sarah Math", "email": "sarah@state.edu", "phone": "(555) 234-5680", "avatar": "https://images.unsplash.com/photo-1494790108377-be9c29b29330?w=200&auto=format&fit=crop&q=60", "venue": "A+ Calculus Tutoring", "description": "Ace your midterms. I got you.", "cover": "https://images.unsplash.com/photo-1635070041078-e363dbe005cb?w=800&auto=format&fit=crop&q=60", "category": "Academic", "bio": "Hey there! I''m Sarah, 21 years old and a junior majoring in Mathematics with a minor in Education. I''m from Boston and I absolutely love teaching! I''ve been tutoring since my freshman year and have helped over 100 students pass their calculus courses. Math doesn''t have to be scary - I break it down in ways that actually make sense. When I''m not tutoring or studying, I love reading mystery novels (Agatha Christie is my favorite), going for runs around campus, and trying new recipes. My favorite movies are Good Will Hunting and The Imitation Game. I''m also really into board games and host a weekly game night with friends. I believe everyone can succeed in math with the right approach and a bit of patience. Let''s tackle those derivatives together!", "services": [{"name": "1 Hour Session", "desc": "Calculus I or II", "duration": 60, "price": 40}, {"name": "Exam Prep", "desc": "Group session (max 4)", "duration": 90, "price": 20}, {"name": "Homework Help", "desc": "Quick questions", "duration": 30, "price": 25}, {"name": "Final Review", "desc": "Comprehensive review", "duration": 120, "price": 60}]},
                {"name": "Robert Kim", "email": "robert@state.edu", "phone": "(555) 234-5681", "avatar": "https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?w=200&auto=format&fit=crop&q=60", "venue": "Robert''s Physics Tutoring", "description": "Physics I, II, and mechanics help.", "cover": "https://images.unsplash.com/photo-1636466497217-26a8cbeaf0aa?w=800&auto=format&fit=crop&q=60", "category": "Academic", "bio": "What''s up! I''m Robert, 23 years old and a graduate student working on my Master''s in Physics. I''m originally from Seattle and I''ve been passionate about physics since high school. I love helping students understand how the world works - from quantum mechanics to classical physics. When I''m not teaching or doing research, I''m usually playing video games (big fan of puzzle games and RPGs), watching sci-fi shows like The Expanse, or tinkering with electronics. My favorite movies are Interstellar and The Matrix. I also enjoy hiking and photography, especially astrophotography. I''m a coffee enthusiast and always down to discuss physics concepts over a good cup of coffee. Physics can be challenging, but I''m here to make it accessible and fun!", "services": [{"name": "Physics I Help", "desc": "Mechanics and motion", "duration": 60, "price": 45}, {"name": "Physics II Help", "desc": "Electricity and magnetism", "duration": 60, "price": 45}, {"name": "Lab Report Help", "desc": "Write-up assistance", "duration": 90, "price": 50}, {"name": "Exam Prep", "desc": "Comprehensive review", "duration": 120, "price": 70}]},
                {"name": "Cam Lens", "email": "cam@state.edu", "phone": "(555) 234-5682", "avatar": "https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?w=200&auto=format&fit=crop&q=60", "venue": "Grad Portraits", "description": "Professional headshots and senior portraits.", "cover": "https://images.unsplash.com/photo-1516035069371-29a1b244cc32?w=800&auto=format&fit=crop&q=60", "category": "Photography/Videography", "bio": "Hey! I''m Cam, 22 years old and a senior majoring in Film & Media Studies. I''m from Portland, Oregon and I''ve been doing photography for about 6 years now. I specialize in portrait photography and love capturing people''s personalities and emotions. I''ve shot everything from senior portraits to music festivals to corporate headshots. When I''m not behind the camera, I''m usually editing photos, watching films (I''m a huge cinephile - favorites include Blade Runner 2049 and Her), or exploring new locations for shoots. I love indie music and going to concerts. I also enjoy rock climbing and have been doing it for 3 years. My goal is to help you look your absolute best and create photos you''ll treasure forever. I work with natural light and have a relaxed, fun approach to sessions!", "services": [{"name": "Headshot Mini", "desc": "15 min, 3 edited", "duration": 15, "price": 50}, {"name": "Senior Portrait", "desc": "1 hour, 2 locations, 20 photos", "duration": 60, "price": 150}, {"name": "LinkedIn Photo", "desc": "Professional headshot", "duration": 20, "price": 40}, {"name": "Graduation Package", "desc": "Full ceremony coverage", "duration": 180, "price": 300}]},
                {"name": "DJ Spin", "email": "dj@state.edu", "phone": "(555) 234-5683", "avatar": "https://images.unsplash.com/photo-1506794778202-cad84cf45f1d?w=200&auto=format&fit=crop&q=60", "venue": "Campus DJ Services", "description": "Available for frat parties and events.", "cover": "https://images.unsplash.com/photo-1493225457124-a3eb161ffa5f?w=800&auto=format&fit=crop&q=60", "category": "Events", "bio": "What''s good! I''m DJ Spin, 20 years old and a sophomore majoring in Music Production. I''m from Miami and I''ve been DJing since I was 16. I love creating energy and getting people moving on the dance floor! I spin everything from hip-hop and EDM to house and Latin music. I''ve DJ''d at parties, clubs, and events all over campus. When I''m not behind the decks, I''m producing beats, discovering new music, or hanging out with friends. My favorite movies are 8 Mile and Straight Outta Compton. I''m really into sneaker culture and have a pretty solid collection. I also love playing basketball and video games. I bring professional equipment and know how to read a crowd to keep the energy high all night. Let''s make your event unforgettable!", "services": [{"name": "Party Set", "desc": "4 hour party", "duration": 240, "price": 300}, {"name": "Event DJ", "desc": "6 hour event", "duration": 360, "price": 450}, {"name": "Sound System Rental", "desc": "Speakers + setup", "duration": 480, "price": 200}]},
                {"name": "David Chen", "email": "david@state.edu", "phone": "(555) 234-5684", "avatar": "https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?w=200&auto=format&fit=crop&q=60", "venue": "David''s Fitness Coaching", "description": "Personal training and nutrition plans.", "cover": "https://images.unsplash.com/photo-1534438327276-14e5300c3a48?w=800&auto=format&fit=crop&q=60", "category": "Fitness", "bio": "Hey! I''m David, 25 years old and a graduate student studying Exercise Science. I''m from San Francisco and I''ve been into fitness for over 8 years. I''m a certified personal trainer and nutrition coach. I love helping people transform their bodies and build confidence through fitness. When I''m not training clients or studying, I''m lifting weights, meal prepping, or watching fitness content on YouTube. My favorite movies are Rocky and Warrior. I''m really into MMA and follow UFC religiously. I also enjoy cooking healthy meals and trying new recipes. I believe fitness should be sustainable and enjoyable, not a punishment. Let''s build strength, improve your health, and have fun doing it!", "services": [{"name": "1-on-1 Training", "desc": "Personal session", "duration": 60, "price": 50}, {"name": "Group Workout", "desc": "Small group (3-5)", "duration": 60, "price": 20}, {"name": "Nutrition Consult", "desc": "Meal planning", "duration": 45, "price": 40}, {"name": "Monthly Package", "desc": "8 sessions/month", "duration": 480, "price": 320}]},
                {"name": "Olivia Martinez", "email": "olivia@state.edu", "phone": "(555) 234-5685", "avatar": "https://images.unsplash.com/photo-1494790108377-be9c29b29330?w=200&auto=format&fit=crop&q=60", "venue": "Olivia''s Yoga Studio", "description": "Vinyasa, hot yoga, and meditation.", "cover": "https://images.unsplash.com/photo-1545205597-3d9d02c29597?w=800&auto=format&fit=crop&q=60", "category": "Fitness", "bio": "Namaste! I''m Olivia, 23 years old and a senior majoring in Psychology. I''m from Boulder, Colorado and I''ve been practicing yoga for 6 years. I''m a certified yoga instructor (200-hour RYT) and love sharing the practice with others. Yoga changed my life and I want to help others find that same peace and strength. When I''m not teaching yoga, I''m meditating, reading spiritual books, or hiking in nature. My favorite movies are Eat Pray Love and The Secret Life of Walter Mitty. I''m really into holistic wellness, essential oils, and herbal teas. I also love journaling and practicing gratitude daily. My classes are welcoming to all levels - whether you''re a complete beginner or experienced practitioner, you''ll find a place here. Let''s flow together!", "services": [{"name": "Vinyasa Flow", "desc": "60 min flow class", "duration": 60, "price": 15}, {"name": "Hot Yoga", "desc": "90 min hot session", "duration": 90, "price": 20}, {"name": "Meditation", "desc": "Guided meditation", "duration": 30, "price": 10}, {"name": "Private Session", "desc": "1-on-1 instruction", "duration": 60, "price": 50}]},
                {"name": "James Rodriguez", "email": "james@state.edu", "phone": "(555) 234-5686", "avatar": "https://images.unsplash.com/photo-1500648767791-00dcc994a43e?w=200&auto=format&fit=crop&q=60", "venue": "James''s Guitar Lessons", "description": "Acoustic and electric guitar instruction.", "cover": "https://images.unsplash.com/photo-1510915361894-db8b60106cb1?w=800&auto=format&fit=crop&q=60", "category": "Music", "bio": "Hey! I''m James, 21 years old and a junior majoring in Music Performance. I''m from Austin, Texas and I''ve been playing guitar for 10 years. I play everything from classical to rock to jazz. I love teaching and seeing students progress! When I''m not teaching or practicing, I''m writing songs, going to local shows, or jamming with friends. My favorite movies are Whiplash and La La Land. I''m really into vinyl records and have a growing collection. I also enjoy coffee shops, reading music biographies, and trying new restaurants. Music is my life and I want to share that passion with you. Whether you want to learn your favorite songs or dive deep into music theory, I''m here to help!", "services": [{"name": "Beginner Lesson", "desc": "Learn basics", "duration": 60, "price": 30}, {"name": "Advanced Technique", "desc": "For experienced players", "duration": 60, "price": 40}, {"name": "Song Learning", "desc": "Learn your favorite song", "duration": 45, "price": 35}, {"name": "Group Class", "desc": "3-4 students", "duration": 60, "price": 15}]},
                {"name": "Chris Thompson", "email": "chris@state.edu", "phone": "(555) 234-5687", "avatar": "https://images.unsplash.com/photo-1472099645785-5658abf4ff4e?w=200&auto=format&fit=crop&q=60", "venue": "Chris''s Moving Service", "description": "Dorm move-in and move-out help.", "cover": "https://images.unsplash.com/photo-1600518464441-9154a4dea21b?w=800&auto=format&fit=crop&q=60", "category": "Services", "bio": "What''s up! I''m Chris, 24 years old and a senior majoring in Business. I''m from Detroit and I started this moving service to help students during move-in and move-out seasons. I''ve been doing this for 3 years now and have helped hundreds of students. I''m reliable, careful with your stuff, and always on time. When I''m not moving furniture, I''m working out, watching sports (big Lions and Pistons fan), or hanging out with friends. My favorite movies are The Shawshank Redemption and Gladiator. I love action movies and video games. I also enjoy cooking and trying new restaurants. Moving can be stressful, but I''m here to make it easy. I bring all the equipment needed and work efficiently. Let''s get you moved in or out smoothly!", "services": [{"name": "Small Move", "desc": "1-2 rooms", "duration": 120, "price": 80}, {"name": "Full Dorm Move", "desc": "Complete move", "duration": 240, "price": 150}, {"name": "Heavy Lifting", "desc": "Furniture only", "duration": 60, "price": 50}, {"name": "Packing Service", "desc": "We pack for you", "duration": 180, "price": 100}]},
                {"name": "Sophie Brown", "email": "sophie@state.edu", "phone": "(555) 234-5688", "avatar": "https://images.unsplash.com/photo-1534528741775-53994a69daeb?w=200&auto=format&fit=crop&q=60", "venue": "Sophie''s Cleaning Service", "description": "Dorm and apartment cleaning.", "cover": "https://images.unsplash.com/photo-1581578731548-c64695cc6952?w=800&auto=format&fit=crop&q=60", "category": "Services", "bio": "Hi! I''m Sophie, 22 years old and a senior majoring in Environmental Science. I''m from Portland, Maine and I''ve been cleaning professionally for 4 years. I love creating clean, organized spaces! I use eco-friendly products and pay attention to every detail. When I''m not cleaning, I''m studying, reading (love mystery novels), or doing yoga. My favorite movies are The Devil Wears Prada and Legally Blonde. I''m really into sustainability and zero-waste living. I also enjoy gardening, hiking, and spending time with my cat. A clean space helps create a clear mind, and I''m here to help you achieve that. I''m thorough, reliable, and I''ll leave your place spotless!", "services": [{"name": "Deep Clean", "desc": "Full apartment clean", "duration": 180, "price": 75}, {"name": "Weekly Clean", "desc": "Maintenance cleaning", "duration": 90, "price": 40}, {"name": "Move-Out Clean", "desc": "Post-move cleaning", "duration": 120, "price": 60}, {"name": "Bathroom Deep Clean", "desc": "Bathroom only", "duration": 60, "price": 35}]},
                {"name": "Tom Williams", "email": "tom@state.edu", "phone": "(555) 234-5689", "avatar": "https://images.unsplash.com/photo-1500648767791-00dcc994a43e?w=200&auto=format&fit=crop&q=60", "venue": "Tom''s Car Detailing", "description": "Mobile car wash and detailing.", "cover": "https://images.unsplash.com/photo-1520340356584-f9917d1eea6f?w=800&auto=format&fit=crop&q=60", "category": "Services", "bio": "Hey! I''m Tom, 26 years old and I graduated last year with a degree in Automotive Technology. I''m from Phoenix, Arizona and I''ve been detailing cars since I was 18. I''m passionate about making cars look their absolute best! I offer mobile service so you don''t have to go anywhere. When I''m not detailing, I''m working on my own car projects, watching car shows (Top Gear is my favorite), or going to car meets. My favorite movies are Fast & Furious and Ford v Ferrari. I''m really into car culture and love talking about modifications and builds. I also enjoy fishing and camping on weekends. I use premium products and take pride in my work. Your car will look showroom-ready when I''m done!", "services": [{"name": "Basic Wash", "desc": "Exterior wash", "duration": 45, "price": 25}, {"name": "Full Detail", "desc": "Interior + exterior", "duration": 180, "price": 100}, {"name": "Wax & Polish", "desc": "Wax treatment", "duration": 90, "price": 60}, {"name": "Interior Detail", "desc": "Deep interior clean", "duration": 120, "price": 75}]},
                {"name": "Emily Davis", "email": "emily@state.edu", "phone": "(555) 234-5690", "avatar": "https://images.unsplash.com/photo-1534528741775-53994a69daeb?w=200&auto=format&fit=crop&q=60", "venue": "Emily''s Pet Sitting", "description": "Dog walking and pet care.", "cover": "https://images.unsplash.com/photo-1587300003388-59208cc962cb?w=800&auto=format&fit=crop&q=60", "category": "Services", "bio": "Hi there! I''m Emily, 20 years old and a sophomore majoring in Veterinary Science. I''m from Denver, Colorado and I absolutely adore animals! I''ve been pet sitting and dog walking for 5 years. I have experience with all types of pets - dogs, cats, birds, reptiles, you name it! When I''m not caring for pets or studying, I''m volunteering at the local animal shelter, watching animal documentaries, or spending time with my own dog, Max. My favorite movies are Marley & Me and The Secret Life of Pets. I''m really into animal behavior and training. I also enjoy hiking with dogs and photography. Your pets will be in loving, capable hands with me. I treat every pet like my own!", "services": [{"name": "Dog Walk", "desc": "30 min walk", "duration": 30, "price": 15}, {"name": "Pet Sitting", "desc": "Overnight care", "duration": 1440, "price": 50}, {"name": "Pet Grooming", "desc": "Bath and trim", "duration": 90, "price": 40}, {"name": "Daily Visits", "desc": "Check-in and feed", "duration": 30, "price": 20}]},
                {"name": "Lisa Anderson", "email": "lisa@state.edu", "phone": "(555) 234-5691", "avatar": "https://images.unsplash.com/photo-1494790108377-be9c29b29330?w=200&auto=format&fit=crop&q=60", "venue": "Lisa''s Resume Writing", "description": "Professional resume and cover letter help.", "cover": "https://images.unsplash.com/photo-1586281380349-632531db7ed4?w=800&auto=format&fit=crop&q=60", "category": "Professional", "bio": "Hello! I''m Lisa, 23 years old and a graduate student working on my MBA. I''m from New York City and I have 3 years of experience in HR and recruiting. I''ve reviewed thousands of resumes and know exactly what employers are looking for. I help students land internships and jobs by crafting compelling resumes and cover letters. When I''m not writing resumes or studying, I''m networking, reading business books, or exploring the city. My favorite movies are The Pursuit of Happyness and The Intern. I''m really into personal development and career coaching. I also enjoy coffee shops, podcasts, and trying new restaurants. Your resume is your first impression - let''s make it count! I''ll help you highlight your strengths and stand out from the crowd.", "services": [{"name": "Resume Review", "desc": "Feedback and edits", "duration": 60, "price": 35}, {"name": "Resume Rewrite", "desc": "Complete rewrite", "duration": 90, "price": 60}, {"name": "Cover Letter", "desc": "Custom cover letter", "duration": 45, "price": 30}, {"name": "LinkedIn Profile", "desc": "Optimize your profile", "duration": 60, "price": 40}]},
                {"name": "Jake''s Bar & Grill", "email": "jake@state.edu", "phone": "(555) 234-5692", "avatar": "https://images.unsplash.com/photo-1555396273-367ea4eb4db5?w=200&auto=format&fit=crop&q=60", "venue": "Jake''s Bar & Grill", "description": "Best burgers and wings on campus. Open late.", "cover": "https://images.unsplash.com/photo-1555396273-367ea4eb4db5?w=800&auto=format&fit=crop&q=60", "category": "Food", "bio": "Hey! I''m Jake, 28 years old and the owner of Jake''s Bar & Grill. I''m from Buffalo, New York originally, but I''ve been running this place for 5 years now. I''m not a student - I''m a licensed restaurant owner who loves serving the campus community! I''ve been in the restaurant business for 10 years, working my way up from line cook to owner. When I''m not running the restaurant, I''m watching sports (huge Bills and Sabres fan), trying new recipes, or hanging out with my dog, Buddy. My favorite movies are Goodfellas and The Godfather. I love classic rock and going to concerts. I''m passionate about good food, cold beer, and creating a fun atmosphere. Come grab a burger and let''s talk sports!", "services": [{"name": "Table Reservation", "desc": "Reserve a table for 2-8", "duration": 120, "price": 0}, {"name": "Group Booking", "desc": "Reserve for 8+ people", "duration": 180, "price": 0}, {"name": "Catering", "desc": "Catering for events (20+ people)", "duration": 240, "price": 200}, {"name": "Late Night Delivery", "desc": "Food delivery after 10pm", "duration": 45, "price": 5}]},
                {"name": "Campus Coffee Co", "email": "coffee@state.edu", "phone": "(555) 234-5693", "avatar": "https://images.unsplash.com/photo-1509042239860-f550ce710b93?w=200&auto=format&fit=crop&q=60", "venue": "Campus Coffee Co", "description": "Artisan coffee and pastries. Study-friendly atmosphere.", "cover": "https://images.unsplash.com/photo-1501339847302-ac426a4a7cbb?w=800&auto=format&fit=crop&q=60", "category": "Food", "bio": "Hi! I''m the owner of Campus Coffee Co. I''m 32 years old and originally from Seattle. I''m a licensed barista and certified coffee roaster - not a student, but I love being part of the campus community! I''ve been in the coffee business for 12 years, starting as a barista and working my way up. I source beans directly from farms and roast them myself. When I''m not at the shop, I''m traveling to coffee farms, reading about coffee origins, or experimenting with new brewing methods. My favorite movies are The Secret Life of Walter Mitty and Amélie. I love indie music and vinyl records. I also enjoy hiking, photography, and trying new pastries. Coffee is my passion and I want to share that with you. Come study, relax, and enjoy the best coffee on campus!", "services": [{"name": "Coffee Delivery", "desc": "Bulk coffee delivery for events", "duration": 30, "price": 25}, {"name": "Catering Setup", "desc": "Coffee bar setup for events", "duration": 120, "price": 150}, {"name": "Study Group Package", "desc": "Coffee + snacks for groups", "duration": 60, "price": 40}, {"name": "Private Event", "desc": "Reserve space for private event", "duration": 180, "price": 100}]},
                {"name": "The Study Spot", "email": "study@state.edu", "phone": "(555) 234-5694", "avatar": "https://images.unsplash.com/photo-1555396273-367ea4eb4db5?w=200&auto=format&fit=crop&q=60", "venue": "The Study Spot", "description": "Quiet cafe perfect for studying. Great WiFi.", "cover": "https://images.unsplash.com/photo-1521017432531-fbd92d768814?w=800&auto=format&fit=crop&q=60", "category": "Food", "bio": "Hello! I''m the owner of The Study Spot. I''m 30 years old and from Portland, Oregon. I''m a licensed restaurant owner who created this space specifically for students. I''m not a student myself, but I remember how hard it was to find good study spaces! I''ve been running cafes for 8 years. When I''m not at the cafe, I''m reading (love sci-fi and fantasy), working on my own projects, or exploring the city. My favorite movies are The Matrix and Inception. I''m really into board games and host monthly game nights. I also enjoy cooking, trying new restaurants, and going to concerts. I designed this space to be the perfect study environment - quiet, comfortable, with great coffee and food. Come focus, get work done, and fuel up!", "services": [{"name": "Table Reservation", "desc": "Reserve a study table", "duration": 120, "price": 0}, {"name": "Group Study Room", "desc": "Private room for 4-6", "duration": 180, "price": 20}, {"name": "Meal Combo", "desc": "Meal + drink combo", "duration": 60, "price": 12}, {"name": "Event Catering", "desc": "Catering for study groups", "duration": 90, "price": 50}]},
                {"name": "Pizza Palace", "email": "pizza@state.edu", "phone": "(555) 234-5695", "avatar": "https://images.unsplash.com/photo-1513104890138-7c749659a591?w=200&auto=format&fit=crop&q=60", "venue": "Pizza Palace", "description": "Late night pizza delivery. Open until 2am.", "cover": "https://images.unsplash.com/photo-1565299624946-b28f40a0ae38?w=800&auto=format&fit=crop&q=60", "category": "Food", "bio": "Hey! I''m the owner of Pizza Palace. I''m 29 years old and from New York City - born and raised in Brooklyn! I''m a licensed food service operator, not a student. I''ve been making pizza since I was 16, learning from my Italian grandfather''s recipe. I opened this place 4 years ago to serve the late-night crowd. When I''m not making pizza, I''m watching the Yankees play, trying new pizza places, or hanging out with friends. My favorite movies are The Godfather and Goodfellas. I love Italian food, classic rock, and New York sports teams. I also enjoy cooking, going to concerts, and playing basketball. I make authentic New York-style pizza with fresh ingredients. Perfect for late-night study sessions or parties. Order up!", "services": [{"name": "Pizza Delivery", "desc": "Delivery to dorms", "duration": 30, "price": 3}, {"name": "Party Package", "desc": "Multiple pizzas for parties", "duration": 45, "price": 50}, {"name": "Catering", "desc": "Catering for events", "duration": 60, "price": 100}, {"name": "Pickup Order", "desc": "Order ahead pickup", "duration": 15, "price": 0}]},
                {"name": "Anna Lopez", "email": "anna@state.edu", "phone": "(555) 234-5696", "avatar": "https://images.unsplash.com/photo-1534528741775-53994a69daeb?w=200&auto=format&fit=crop&q=60", "venue": "Anna''s Cooking Classes", "description": "Learn to cook delicious meals.", "cover": "https://images.unsplash.com/photo-1556910103-1c02745aae4d?w=800&auto=format&fit=crop&q=60", "category": "Food", "bio": "Hola! I''m Anna, 25 years old and a graduate student studying Culinary Arts. I''m from San Antonio, Texas and I''ve been cooking since I could reach the stove! I come from a big Mexican family where cooking is a way of life. I love teaching others how to cook and share my passion for food. When I''m not teaching classes or studying, I''m experimenting with new recipes, watching cooking shows, or hosting dinner parties for friends. My favorite movies are Ratatouille and Julie & Julia. I''m really into food photography and have an Instagram where I share my creations. I also enjoy salsa dancing, trying new restaurants, and traveling to experience different cuisines. Cooking brings people together and I want to help you create amazing meals. Let''s get cooking!", "services": [{"name": "Italian Cooking", "desc": "Pasta and sauces", "duration": 120, "price": 45}, {"name": "Baking Basics", "desc": "Cakes and cookies", "duration": 90, "price": 40}, {"name": "Meal Prep", "desc": "Weekly meal planning", "duration": 180, "price": 60}, {"name": "Date Night Cooking", "desc": "Romantic dinner for two", "duration": 150, "price": 80}]},
                {"name": "The Underground", "email": "underground@state.edu", "phone": "(555) 234-5697", "avatar": "https://images.unsplash.com/photo-1514933651103-005eec06c04b?w=200&auto=format&fit=crop&q=60", "venue": "The Underground", "description": "Campus bar with live music. 21+ only.", "cover": "https://images.unsplash.com/photo-1514362545857-3bc16c4c7d1b?w=800&auto=format&fit=crop&q=60", "category": "Food", "bio": "What''s up! I''m the owner of The Underground. I''m 35 years old and from Nashville, Tennessee. I''m a licensed bar and restaurant owner - definitely not a student! I''ve been in the bar business for 15 years, working everywhere from dive bars to upscale cocktail lounges. I opened The Underground 6 years ago to bring live music and great drinks to campus. When I''m not running the bar, I''m playing guitar, going to shows, or checking out new bands. My favorite movies are Almost Famous and Walk the Line. I love all kinds of music - rock, country, blues, you name it. I also enjoy whiskey tasting, cooking, and traveling. I book local bands every weekend and serve craft cocktails. Come grab a drink, catch some live music, and have a great time!", "services": [{"name": "Table Reservation", "desc": "Reserve a table", "duration": 120, "price": 0}, {"name": "Private Event", "desc": "Reserve space for private event", "duration": 240, "price": 200}, {"name": "Bar Rental", "desc": "Rent the bar for private party", "duration": 360, "price": 500}, {"name": "Catering", "desc": "Food and drinks for events", "duration": 180, "price": 300}]},
                {"name": "Meal Prep Masters", "email": "mealprep@state.edu", "phone": "(555) 234-5698", "avatar": "https://images.unsplash.com/photo-1546069901-ba9599a7e63c?w=200&auto=format&fit=crop&q=60", "venue": "Meal Prep Masters", "description": "Weekly meal prep service. Healthy and affordable.", "cover": "https://images.unsplash.com/photo-1546069901-ba9599a7e63c?w=800&auto=format&fit=crop&q=60", "category": "Food", "bio": "Hi! I''m the owner of Meal Prep Masters. I''m 31 years old and from Los Angeles, California. I''m a licensed food service operator and certified nutritionist - not a student, but I love helping students eat healthy! I''ve been meal prepping for 8 years and started this business 3 years ago. I''m passionate about making healthy eating easy and affordable. When I''m not prepping meals, I''m working out, trying new healthy recipes, or reading nutrition research. My favorite movies are The Pursuit of Happyness and Chef. I''m really into fitness, meal planning, and food photography. I also enjoy hiking, yoga, and going to farmers markets. Eating healthy doesn''t have to be expensive or time-consuming. I prep everything fresh weekly with high-quality ingredients. Let''s fuel your body right!", "services": [{"name": "Weekly Meal Prep", "desc": "5 meals for the week", "duration": 60, "price": 50}, {"name": "Custom Meal Plan", "desc": "Personalized meal plan", "duration": 90, "price": 75}, {"name": "Bulk Order", "desc": "Meal prep for groups", "duration": 120, "price": 200}, {"name": "Nutrition Consult", "desc": "Meal planning consultation", "duration": 45, "price": 30}]}
            ]
        },
        {
            "campus": "Ivy College",
            "providers": [
                {"name": "James Prep", "email": "james@ivy.edu", "phone": "(555) 345-6701", "avatar": "https://images.unsplash.com/photo-1500648767791-00dcc994a43e?w=200&auto=format&fit=crop&q=60", "venue": "Elite LSAT Prep", "description": "Get into Harvard Law.", "cover": "https://images.unsplash.com/photo-1589829545856-d10d557cf95f?w=800&auto=format&fit=crop&q=60", "category": "Academic", "bio": "Hey! I''m James, 24 years old and a recent graduate from Harvard Law School. I''m from Boston originally and I scored in the 99th percentile on the LSAT. I''ve been tutoring LSAT prep for 3 years and have helped dozens of students get into top law schools. When I''m not tutoring, I''m reading legal cases, watching legal dramas (The Good Wife is my favorite), or playing chess. My favorite movies are A Few Good Men and The Paper Chase. I''m really into debate, philosophy, and political science. I also enjoy running, reading mystery novels, and trying new coffee shops. The LSAT is challenging but totally beatable with the right strategy. Let''s get you into your dream law school!", "services": [{"name": "LSAT Drill", "desc": "Logic games practice", "duration": 60, "price": 120}, {"name": "Full Practice Test", "desc": "Timed full exam", "duration": 175, "price": 150}, {"name": "Reading Comp", "desc": "Reading strategies", "duration": 90, "price": 100}, {"name": "Analytical Reasoning", "desc": "Logic games mastery", "duration": 60, "price": 120}]},
                {"name": "Victoria Chen", "email": "victoria@ivy.edu", "phone": "(555) 345-6702", "avatar": "https://images.unsplash.com/photo-1534528741775-53994a69daeb?w=200&auto=format&fit=crop&q=60", "venue": "Victoria''s GMAT Prep", "description": "Score 750+ on the GMAT.", "cover": "https://images.unsplash.com/photo-1434030216411-0b793f4b4173?w=800&auto=format&fit=crop&q=60", "category": "Academic", "bio": "Hi! I''m Victoria, 25 years old and a graduate student at Wharton Business School. I''m from San Francisco and I scored 780 on the GMAT. I''ve been tutoring GMAT prep for 4 years and specialize in helping students break 750+. When I''m not tutoring or studying, I''m reading business books, watching TED talks, or networking. My favorite movies are The Social Network and The Big Short. I''m really into entrepreneurship, finance, and business strategy. I also enjoy yoga, trying new restaurants, and traveling. The GMAT is a learnable test - with the right approach, you can achieve your target score. Let''s make it happen!", "services": [{"name": "Quant Review", "desc": "Math section prep", "duration": 90, "price": 110}, {"name": "Verbal Mastery", "desc": "Reading and grammar", "duration": 90, "price": 110}, {"name": "Full Practice Test", "desc": "Timed exam simulation", "duration": 210, "price": 140}, {"name": "Essay Writing", "desc": "AWA section help", "duration": 60, "price": 90}]},
                {"name": "Nathaniel Brooks", "email": "nathaniel@ivy.edu", "phone": "(555) 345-6703", "avatar": "https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?w=200&auto=format&fit=crop&q=60", "venue": "Nathaniel''s SAT Tutoring", "description": "Perfect 1600 score prep.", "cover": "https://images.unsplash.com/photo-1456513080510-7bf3a84b82f8?w=800&auto=format&fit=crop&q=60", "category": "Academic", "bio": "Hey! I''m Nathaniel, 23 years old and a senior majoring in Education. I''m from New York City and I scored a perfect 1600 on the SAT. I''ve been tutoring SAT prep for 5 years and have helped over 200 students improve their scores. When I''m not tutoring, I''m studying education theory, reading about teaching methods, or playing piano. My favorite movies are Dead Poets Society and Stand and Deliver. I''m really into education reform, psychology, and literature. I also enjoy classical music, going to museums, and trying new cuisines. The SAT is a standardized test that rewards strategy and practice. I''ll teach you the tricks and help you maximize your score!", "services": [{"name": "Math Section", "desc": "Algebra and geometry", "duration": 90, "price": 95}, {"name": "Reading & Writing", "desc": "Verbal sections", "duration": 90, "price": 95}, {"name": "Full Practice Test", "desc": "Timed exam", "duration": 180, "price": 120}, {"name": "Essay Writing", "desc": "Optional essay help", "duration": 60, "price": 70}]},
                {"name": "Amelia White", "email": "amelia@ivy.edu", "phone": "(555) 345-6704", "avatar": "https://images.unsplash.com/photo-1494790108377-be9c29b29330?w=200&auto=format&fit=crop&q=60", "venue": "Amelia''s French Tutoring", "description": "Native speaker, all levels.", "cover": "https://images.unsplash.com/photo-1549144511-f099e773c147?w=800&auto=format&fit=crop&q=60", "category": "Academic", "bio": "Bonjour! I''m Amelia, 22 years old and a senior majoring in French Literature. I''m originally from Paris, France but moved to the US when I was 12. I''m a native French speaker and I''ve been tutoring French for 4 years. I love sharing my language and culture with others! When I''m not tutoring, I''m reading French novels, watching French films, or cooking French cuisine. My favorite movies are Amélie and The Intouchables. I''m really into French cinema, art, and history. I also enjoy traveling, photography, and going to art galleries. Learning French opens up a whole new world of culture and opportunities. Let''s make it fun and engaging!", "services": [{"name": "Conversation Practice", "desc": "Speaking fluency", "duration": 60, "price": 45}, {"name": "Grammar Review", "desc": "Verb conjugations", "duration": 60, "price": 40}, {"name": "Exam Prep", "desc": "Test preparation", "duration": 90, "price": 55}, {"name": "Business French", "desc": "Professional French", "duration": 60, "price": 50}]},
                {"name": "Charlotte Moore", "email": "charlotte@ivy.edu", "phone": "(555) 345-6705", "avatar": "https://images.unsplash.com/photo-1494790108377-be9c29b29330?w=200&auto=format&fit=crop&q=60", "venue": "Charlotte''s Medical School Prep", "description": "MCAT and application help.", "cover": "https://images.unsplash.com/photo-1576091160550-2173dba999ef?w=800&auto=format&fit=crop&q=60", "category": "Academic", "bio": "Hi! I''m Charlotte, 24 years old and a first-year medical student at Harvard Medical School. I''m from Chicago and I scored in the 99th percentile on the MCAT. I''ve been tutoring MCAT prep for 2 years and I understand exactly what it takes to get into medical school. When I''m not studying medicine or tutoring, I''m volunteering at hospitals, reading medical journals, or exercising. My favorite movies are Patch Adams and The Good Doctor. I''m really into medical research, public health, and healthcare policy. I also enjoy running, cooking healthy meals, and spending time with friends. The MCAT and medical school applications are challenging, but I''m here to guide you through every step. Let''s get you into med school!", "services": [{"name": "MCAT Biology", "desc": "Bio section prep", "duration": 90, "price": 125}, {"name": "MCAT Chemistry", "desc": "Chem section prep", "duration": 90, "price": 125}, {"name": "Personal Statement", "desc": "Essay editing", "duration": 60, "price": 100}, {"name": "Interview Prep", "desc": "MMI practice", "duration": 90, "price": 120}]},
                {"name": "Elizabeth Law", "email": "elizabeth@ivy.edu", "phone": "(555) 345-6706", "avatar": "https://images.unsplash.com/photo-1534528741775-53994a69daeb?w=200&auto=format&fit=crop&q=60", "venue": "Case Interview Coach", "description": "McKinsey ready.", "cover": "https://images.unsplash.com/photo-1551836022-d5d88e9218df?w=800&auto=format&fit=crop&q=60", "category": "Professional", "bio": "Hey! I''m Elizabeth, 26 years old and a former McKinsey consultant. I''m from Washington D.C. and I worked at McKinsey for 3 years before starting my own consulting practice. I''ve conducted hundreds of case interviews and know exactly what consulting firms are looking for. When I''m not coaching, I''m reading business cases, watching business documentaries, or networking. My favorite movies are The Wolf of Wall Street and Margin Call. I''m really into business strategy, problem-solving, and helping others succeed. I also enjoy traveling, trying new restaurants, and playing tennis. Case interviews are challenging but I''ll teach you the frameworks and mindset to ace them. Let''s get you that consulting offer!", "services": [{"name": "Mock Interview", "desc": "Full case interview", "duration": 60, "price": 150}, {"name": "Framework Training", "desc": "Learn frameworks", "duration": 90, "price": 120}, {"name": "Resume Review", "desc": "Consulting resume", "duration": 45, "price": 80}, {"name": "Networking Prep", "desc": "Coffee chat prep", "duration": 30, "price": 50}]},
                {"name": "Alexander Grant", "email": "alexander@ivy.edu", "phone": "(555) 345-6707", "avatar": "https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?w=200&auto=format&fit=crop&q=60", "venue": "Alexander''s Investment Banking Prep", "description": "Wall Street ready.", "cover": "https://images.unsplash.com/photo-1611974789855-9c2a0a7236a3?w=800&auto=format&fit=crop&q=60", "category": "Professional", "bio": "What''s up! I''m Alexander, 27 years old and a former investment banker at Goldman Sachs. I''m from New York City and I worked in IB for 4 years before transitioning to private equity. I''ve interviewed hundreds of candidates and know exactly what banks are looking for. When I''m not coaching, I''m reading financial news, analyzing markets, or playing golf. My favorite movies are The Big Short and Wall Street. I''m really into finance, markets, and helping others break into banking. I also enjoy fine dining, wine tasting, and traveling. Investment banking interviews are tough but I''ll teach you the technical skills and networking strategies to land that offer. Let''s get you to Wall Street!", "services": [{"name": "Technical Interview", "desc": "Finance questions", "duration": 90, "price": 130}, {"name": "Modeling Workshop", "desc": "Excel modeling", "duration": 120, "price": 150}, {"name": "Resume Review", "desc": "IB resume format", "duration": 45, "price": 75}, {"name": "Networking Strategy", "desc": "Connect with bankers", "duration": 60, "price": 100}]},
                {"name": "Coach Arthur", "email": "coach@ivy.edu", "phone": "(555) 345-6708", "avatar": "https://images.unsplash.com/photo-1472099645785-5658abf4ff4e?w=200&auto=format&fit=crop&q=60", "venue": "Private Tennis Lessons", "description": "Clay court expertise.", "cover": "https://images.unsplash.com/photo-1622279457486-62dcc4a431d6?w=800&auto=format&fit=crop&q=60", "category": "Sports", "bio": "Hey! I''m Coach Arthur, 38 years old and a professional tennis coach. I''m from Spain originally but I''ve been coaching in the US for 15 years. I''m a licensed USPTA certified coach - not a student, but I love working with college students! I played professionally for 8 years and reached ATP ranking 150. When I''m not coaching, I''m watching tennis matches, analyzing technique, or playing myself. My favorite movies are Borg vs McEnroe and Battle of the Sexes. I''m really into tennis strategy, fitness, and sports psychology. I also enjoy traveling, trying new restaurants, and reading sports biographies. Tennis is my life and I want to share that passion with you. Whether you''re a beginner or advanced player, I''ll help you improve your game!", "services": [{"name": "Serve Practice", "desc": "Ace your serve", "duration": 45, "price": 80}, {"name": "Groundstroke Clinic", "desc": "Forehand and backhand", "duration": 60, "price": 90}, {"name": "Match Play", "desc": "Practice matches", "duration": 90, "price": 100}, {"name": "Video Analysis", "desc": "Technique review", "duration": 60, "price": 85}]},
                {"name": "Benjamin Stone", "email": "benjamin@ivy.edu", "phone": "(555) 345-6709", "avatar": "https://images.unsplash.com/photo-1500648767791-00dcc994a43e?w=200&auto=format&fit=crop&q=60", "venue": "Benjamin''s Golf Lessons", "description": "Private golf instruction.", "cover": "https://images.unsplash.com/photo-1535131749006-b7f58c99034b?w=800&auto=format&fit=crop&q=60", "category": "Sports", "bio": "Hey! I''m Benjamin, 35 years old and a PGA certified golf instructor. I''m from Augusta, Georgia originally - yes, home of the Masters! I''m a licensed PGA professional, not a student. I''ve been teaching golf for 12 years and I love helping people improve their game. When I''m not teaching, I''m playing golf, watching tournaments, or analyzing swing mechanics. My favorite movies are The Legend of Bagger Vance and Tin Cup. I''m really into golf history, course architecture, and swing biomechanics. I also enjoy fishing, grilling, and spending time outdoors. Golf is a game of precision and patience. I''ll help you develop a consistent swing and lower your scores. Let''s hit the links!", "services": [{"name": "Driving Range", "desc": "Swing mechanics", "duration": 60, "price": 85}, {"name": "Putting Clinic", "desc": "Short game mastery", "duration": 45, "price": 70}, {"name": "On-Course Lesson", "desc": "Play 9 holes", "duration": 180, "price": 150}, {"name": "Video Analysis", "desc": "Swing breakdown", "duration": 60, "price": 90}]},
                {"name": "William Harris", "email": "william@ivy.edu", "phone": "(555) 345-6710", "avatar": "https://images.unsplash.com/photo-1472099645785-5658abf4ff4e?w=200&auto=format&fit=crop&q=60", "venue": "William''s Rowing Coach", "description": "Competitive rowing training.", "cover": "https://images.unsplash.com/photo-1594623930572-300a3011d9ae?w=800&auto=format&fit=crop&q=60", "category": "Sports", "bio": "Hey! I''m William, 29 years old and a former collegiate rower. I''m from Boston and I rowed for Harvard for 4 years. I''m not currently a student, but I love coaching college rowers! I''ve been coaching for 6 years and I specialize in competitive rowing. When I''m not coaching, I''m rowing myself, watching regattas, or analyzing technique videos. My favorite movies are The Social Network and Good Will Hunting. I''m really into rowing technique, strength training, and race strategy. I also enjoy sailing, hiking, and trying new restaurants. Rowing is one of the most demanding sports, but it''s incredibly rewarding. I''ll help you develop power, technique, and mental toughness. Let''s get you race-ready!", "services": [{"name": "Erg Training", "desc": "Indoor rowing", "duration": 60, "price": 70}, {"name": "Water Session", "desc": "On-water practice", "duration": 120, "price": 120}, {"name": "Strength Training", "desc": "Rowing-specific strength", "duration": 60, "price": 65}, {"name": "Race Prep", "desc": "Competition strategy", "duration": 90, "price": 100}]},
                {"name": "Daniel Foster", "email": "daniel@ivy.edu", "phone": "(555) 345-6711", "avatar": "https://images.unsplash.com/photo-1500648767791-00dcc994a43e?w=200&auto=format&fit=crop&q=60", "venue": "Daniel''s Sailing Lessons", "description": "Learn to sail on the Charles.", "cover": "https://images.unsplash.com/photo-1500514966906-fe245eea9344?w=800&auto=format&fit=crop&q=60", "category": "Sports", "bio": "Ahoy! I''m Daniel, 32 years old and a US Sailing certified instructor. I''m from Newport, Rhode Island - sailing capital of the US! I''m a licensed sailing instructor, not a student. I''ve been sailing for 20 years and teaching for 8 years. When I''m not teaching, I''m sailing, watching regattas, or working on boats. My favorite movies are Master and Commander and The Perfect Storm. I''m really into sailing history, navigation, and boat maintenance. I also enjoy fishing, beach activities, and seafood. Sailing is freedom on the water. I''ll teach you everything from basics to racing tactics. Let''s get you on the water!", "services": [{"name": "Beginner Sailing", "desc": "Basic sailing skills", "duration": 180, "price": 150}, {"name": "Racing Tactics", "desc": "Competitive sailing", "duration": 180, "price": 180}, {"name": "Navigation", "desc": "Chart reading", "duration": 120, "price": 120}, {"name": "Safety Course", "desc": "US Sailing certified", "duration": 240, "price": 200}]},
                {"name": "Isabella Taylor", "email": "isabella@ivy.edu", "phone": "(555) 345-6712", "avatar": "https://images.unsplash.com/photo-1534528741775-53994a69daeb?w=200&auto=format&fit=crop&q=60", "venue": "Isabella''s Piano Lessons", "description": "Classical and jazz piano.", "cover": "https://images.unsplash.com/photo-1552422535-c45813c61732?w=800&auto=format&fit=crop&q=60", "category": "Music", "bio": "Hello! I''m Isabella, 23 years old and a graduate student studying Music Performance. I''m from Vienna, Austria originally but moved to the US for college. I''ve been playing piano for 18 years and I specialize in classical and jazz. When I''m not teaching or practicing, I''m performing, listening to music, or composing. My favorite movies are Amadeus and La La Land. I''m really into classical music, jazz history, and music theory. I also enjoy going to concerts, reading music biographies, and trying new restaurants. Music is my life and I love sharing it with others. Whether you want to learn classical pieces or jazz improvisation, I''ll help you develop your skills. Let''s make beautiful music together!", "services": [{"name": "Beginner Piano", "desc": "Learn fundamentals", "duration": 60, "price": 60}, {"name": "Jazz Improvisation", "desc": "Advanced techniques", "duration": 60, "price": 75}, {"name": "Music Theory", "desc": "Theory and composition", "duration": 60, "price": 55}, {"name": "Recital Prep", "desc": "Performance coaching", "duration": 90, "price": 80}]},
                {"name": "Grace Lee", "email": "grace@ivy.edu", "phone": "(555) 345-6713", "avatar": "https://images.unsplash.com/photo-1534528741775-53994a69daeb?w=200&auto=format&fit=crop&q=60", "venue": "Grace''s Violin Lessons", "description": "Classical violin instruction.", "cover": "https://images.unsplash.com/photo-1612225330812-01a9c6b355ec?w=800&auto=format&fit=crop&q=60", "category": "Music", "bio": "Hi! I''m Grace, 22 years old and a senior majoring in Violin Performance. I''m from Seoul, South Korea originally but I''ve been in the US since high school. I''ve been playing violin for 15 years and I''m classically trained. When I''m not teaching or practicing, I''m performing with orchestras, listening to classical music, or studying music history. My favorite movies are The Red Violin and Tár. I''m really into classical music, especially Baroque and Romantic periods. I also enjoy going to concerts, reading, and trying new cuisines. The violin is a beautiful and challenging instrument. I''ll help you develop proper technique and musicality. Let''s create beautiful music!", "services": [{"name": "Beginner Violin", "desc": "Learn basics", "duration": 60, "price": 65}, {"name": "Advanced Technique", "desc": "Master level", "duration": 60, "price": 85}, {"name": "Orchestra Prep", "desc": "Audition prep", "duration": 90, "price": 95}, {"name": "Music Theory", "desc": "Theory for strings", "duration": 60, "price": 55}]},
                {"name": "Henry Clark", "email": "henry@ivy.edu", "phone": "(555) 345-6714", "avatar": "https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?w=200&auto=format&fit=crop&q=60", "venue": "Henry''s Debate Coaching", "description": "Competitive debate training.", "cover": "https://images.unsplash.com/photo-1475721027785-f74eccf877e2?w=800&auto=format&fit=crop&q=60", "category": "Academic", "bio": "Hey! I''m Henry, 21 years old and a junior majoring in Political Science. I''m from Washington D.C. and I''ve been debating competitively for 7 years. I''ve won multiple national tournaments and I love coaching others. When I''m not debating or coaching, I''m reading political news, watching debates, or practicing speeches. My favorite movies are The Great Debaters and Lincoln. I''m really into politics, philosophy, and public speaking. I also enjoy reading, going to political events, and trying new restaurants. Debate teaches critical thinking and communication skills that are valuable everywhere. I''ll help you develop arguments, research skills, and speaking confidence. Let''s win some rounds!", "services": [{"name": "Policy Debate", "desc": "Policy format training", "duration": 90, "price": 80}, {"name": "Public Forum", "desc": "PF format", "duration": 90, "price": 75}, {"name": "Research Help", "desc": "Evidence gathering", "duration": 60, "price": 50}, {"name": "Tournament Prep", "desc": "Competition ready", "duration": 120, "price": 100}]},
                {"name": "Lily Adams", "email": "lily@ivy.edu", "phone": "(555) 345-6715", "avatar": "https://images.unsplash.com/photo-1494790108377-be9c29b29330?w=200&auto=format&fit=crop&q=60", "venue": "Lily''s Art Tutoring", "description": "Portfolio development for art school.", "cover": "https://images.unsplash.com/photo-1460661419201-fd4cecdf8a8b?w=800&auto=format&fit=crop&q=60", "category": "Creative", "bio": "Hi! I''m Lily, 20 years old and a sophomore majoring in Fine Arts. I''m from Portland, Oregon and I''ve been creating art since I was a kid. I specialize in drawing, painting, and digital art. When I''m not creating or teaching, I''m visiting galleries, watching art tutorials, or experimenting with new mediums. My favorite movies are Frida and Big Eyes. I''m really into contemporary art, art history, and creative expression. I also enjoy going to museums, reading art books, and trying new art supplies. Art is about expressing yourself and telling stories. I''ll help you develop your skills and build a portfolio that stands out. Let''s create something amazing!", "services": [{"name": "Portfolio Review", "desc": "Art school portfolio", "duration": 90, "price": 90}, {"name": "Drawing Fundamentals", "desc": "Basic drawing skills", "duration": 120, "price": 70}, {"name": "Painting Techniques", "desc": "Oil and acrylic", "duration": 120, "price": 75}, {"name": "Digital Art", "desc": "Photoshop and Procreate", "duration": 90, "price": 65}]},
                {"name": "The Ivy Club", "email": "ivyclub@ivy.edu", "phone": "(555) 345-6716", "avatar": "https://images.unsplash.com/photo-1514933651103-005eec06c04b?w=200&auto=format&fit=crop&q=60", "venue": "The Ivy Club", "description": "Upscale dining and private events. Members only.", "cover": "https://images.unsplash.com/photo-1517248135467-4c7edcad34c4?w=800&auto=format&fit=crop&q=60", "category": "Food", "bio": "Hello! I''m the general manager of The Ivy Club. I''m 42 years old and from New York City. I''m a licensed restaurant manager with 20 years of fine dining experience - definitely not a student! I''ve worked at some of the best restaurants in the world. When I''m not managing the club, I''m studying wine, traveling, or attending culinary events. My favorite movies are The Menu and Chef''s Table. I''m really into fine dining, wine, and hospitality. I also enjoy golf, reading, and collecting wine. The Ivy Club is an exclusive dining experience for members. We serve exceptional cuisine in an elegant atmosphere. Come experience fine dining at its best!", "services": [{"name": "Table Reservation", "desc": "Reserve a table", "duration": 120, "price": 0}, {"name": "Private Dining", "desc": "Private room for events", "duration": 180, "price": 300}, {"name": "Catering", "desc": "Catering for events", "duration": 240, "price": 500}, {"name": "Wine Tasting", "desc": "Private wine tasting", "duration": 90, "price": 75}]},
                {"name": "The Commons Cafe", "email": "commons@ivy.edu", "phone": "(555) 345-6717", "avatar": "https://images.unsplash.com/photo-1509042239860-f550ce710b93?w=200&auto=format&fit=crop&q=60", "venue": "The Commons Cafe", "description": "Organic coffee and healthy meals. Student favorite.", "cover": "https://images.unsplash.com/photo-1554118811-1e0d58224f24?w=800&auto=format&fit=crop&q=60", "category": "Food", "bio": "Hi! I''m the owner of The Commons Cafe. I''m 36 years old and from Portland, Oregon. I''m a licensed restaurant owner and certified nutritionist - not a student! I opened this cafe 5 years ago to serve healthy, organic food to students. When I''m not at the cafe, I''m sourcing ingredients, developing new recipes, or practicing yoga. My favorite movies are Julie & Julia and Chef. I''m really into organic farming, sustainability, and healthy eating. I also enjoy hiking, reading cookbooks, and going to farmers markets. We serve organic coffee, fresh salads, and healthy meals made with local ingredients. Come fuel your studies with nutritious food!", "services": [{"name": "Coffee Delivery", "desc": "Bulk coffee for events", "duration": 30, "price": 30}, {"name": "Catering Setup", "desc": "Full catering setup", "duration": 120, "price": 200}, {"name": "Study Package", "desc": "Coffee + snacks for study groups", "duration": 60, "price": 50}, {"name": "Private Event", "desc": "Reserve space", "duration": 180, "price": 150}]},
                {"name": "Gourmet Catering", "email": "gourmet@ivy.edu", "phone": "(555) 345-6718", "avatar": "https://images.unsplash.com/photo-1556910103-1c02745aae4d?w=200&auto=format&fit=crop&q=60", "venue": "Gourmet Catering", "description": "Fine dining catering for special events.", "cover": "https://images.unsplash.com/photo-1555244162-803834f70033?w=800&auto=format&fit=crop&q=60", "category": "Food", "bio": "Hello! I''m the owner and head chef of Gourmet Catering. I''m 40 years old and from San Francisco. I''m a licensed caterer and trained chef - not a student! I''ve been in the catering business for 15 years and I specialize in fine dining events. When I''m not catering, I''m developing menus, sourcing ingredients, or attending culinary classes. My favorite movies are The Hundred-Foot Journey and Burnt. I''m really into French cuisine, wine pairing, and event planning. I also enjoy traveling, trying new restaurants, and collecting cookbooks. We create exceptional dining experiences for your special events. From hors d''oeuvres to dessert, we''ll make your event unforgettable!", "services": [{"name": "Event Catering", "desc": "Full service catering", "duration": 240, "price": 400}, {"name": "Hors d''oeuvres", "desc": "Appetizer service", "duration": 120, "price": 250}, {"name": "Dessert Service", "desc": "Dessert catering", "duration": 90, "price": 150}, {"name": "Custom Menu", "desc": "Customized menu planning", "duration": 180, "price": 600}]},
                {"name": "The Library Bar", "email": "librarybar@ivy.edu", "phone": "(555) 345-6719", "avatar": "https://images.unsplash.com/photo-1514933651103-005eec06c04b?w=200&auto=format&fit=crop&q=60", "venue": "The Library Bar", "description": "Speakeasy-style bar. Craft cocktails.", "cover": "https://images.unsplash.com/photo-1572116469696-31de0f17cc34?w=800&auto=format&fit=crop&q=60", "category": "Food", "bio": "Hey! I''m the owner and head bartender of The Library Bar. I''m 33 years old and from New Orleans. I''m a licensed bar owner and certified mixologist - not a student! I''ve been crafting cocktails for 12 years and I opened this speakeasy 4 years ago. When I''m not behind the bar, I''m experimenting with new cocktails, studying cocktail history, or traveling to bars around the world. My favorite movies are The Great Gatsby and Casablanca. I''m really into cocktail history, spirits, and mixology. I also enjoy jazz music, reading, and collecting vintage barware. We serve craft cocktails in a sophisticated speakeasy atmosphere. Come experience the art of mixology!", "services": [{"name": "Table Reservation", "desc": "Reserve a table", "duration": 120, "price": 0}, {"name": "Private Event", "desc": "Reserve bar for private party", "duration": 240, "price": 400}, {"name": "Cocktail Class", "desc": "Learn to make cocktails", "duration": 90, "price": 60}, {"name": "Bar Rental", "desc": "Full bar rental", "duration": 360, "price": 800}]},
                {"name": "Meal Prep Elite", "email": "mealprep@ivy.edu", "phone": "(555) 345-6720", "avatar": "https://images.unsplash.com/photo-1546069901-ba9599a7e63c?w=200&auto=format&fit=crop&q=60", "venue": "Meal Prep Elite", "description": "Premium meal prep service. Organic ingredients.", "cover": "https://images.unsplash.com/photo-1490645935967-10de6ba17061?w=800&auto=format&fit=crop&q=60", "category": "Food", "bio": "Hi! I''m the owner and head chef of Meal Prep Elite. I''m 34 years old and from Los Angeles. I''m a licensed food service operator and certified nutritionist - not a student! I''ve been meal prepping for 10 years and I started this business 4 years ago. When I''m not prepping meals, I''m developing recipes, sourcing organic ingredients, or working out. My favorite movies are Chef and The Pursuit of Happyness. I''m really into nutrition science, meal planning, and healthy cooking. I also enjoy fitness, reading nutrition research, and going to farmers markets. We prepare premium meals with organic ingredients, perfect for busy students. Eat healthy without the hassle!", "services": [{"name": "Weekly Meal Prep", "desc": "5 premium meals", "duration": 60, "price": 75}, {"name": "Custom Meal Plan", "desc": "Personalized nutrition plan", "duration": 90, "price": 100}, {"name": "Bulk Order", "desc": "Meal prep for groups", "duration": 120, "price": 300}, {"name": "Chef Consultation", "desc": "Nutrition consultation", "duration": 60, "price": 50}]},
                {"name": "The Bistro", "email": "bistro@ivy.edu", "phone": "(555) 345-6721", "avatar": "https://images.unsplash.com/photo-1555396273-367ea4eb4db5?w=200&auto=format&fit=crop&q=60", "venue": "The Bistro", "description": "French-inspired bistro. Perfect for dates.", "cover": "https://images.unsplash.com/photo-1550966871-3ed3cdb5ed0c?w=800&auto=format&fit=crop&q=60", "category": "Food", "bio": "Bonjour! I''m the owner and head chef of The Bistro. I''m 38 years old and from Lyon, France originally. I''m a licensed restaurant owner and trained French chef - not a student! I moved to the US 10 years ago and opened this bistro 6 years ago. When I''m not in the kitchen, I''m developing French recipes, studying wine, or traveling back to France. My favorite movies are Ratatouille and Julie & Julia. I''m really into French cuisine, wine, and hospitality. I also enjoy cooking classes, reading cookbooks, and collecting French wines. We serve authentic French cuisine in a romantic bistro atmosphere. Perfect for dates or special occasions. Bon appétit!", "services": [{"name": "Table Reservation", "desc": "Reserve a table", "duration": 120, "price": 0}, {"name": "Private Dining", "desc": "Private room", "duration": 180, "price": 250}, {"name": "Wine Pairing", "desc": "Wine pairing dinner", "duration": 150, "price": 120}, {"name": "Catering", "desc": "Event catering", "duration": 240, "price": 400}]}
