        {
            "campus": "Tech Institute",
            "providers": [
                {"name": "Dev O''Brian", "email": "dev@tech.edu", "phone": "(555) 456-7801", "avatar": "https://images.unsplash.com/photo-1519085360753-af0119f7cbe7?w=200&auto=format&fit=crop&q=60", "venue": "Python & Rust Tutoring", "description": "Segfault no more.", "cover": "https://images.unsplash.com/photo-1526379095098-d400fd0bf935?w=800&auto=format&fit=crop&q=60", "category": "Tech", "bio": "Hey! I''m Dev, 24 years old and a graduate student studying Computer Science. I''m from Seattle and I''ve been programming for 8 years. I specialize in Python and Rust - two of my favorite languages! When I''m not coding or teaching, I''m contributing to open source projects, reading tech blogs, or playing video games. My favorite movies are The Matrix and Ex Machina. I''m really into systems programming, performance optimization, and functional programming. I also enjoy hiking, coffee, and mechanical keyboards. Programming can be challenging but I''ll help you understand the concepts and write better code. Let''s debug together!", "services": [{"name": "Code Review", "desc": "Fix your PR", "duration": 30, "price": 50}, {"name": "Python Basics", "desc": "Learn Python", "duration": 90, "price": 60}, {"name": "Rust Crash Course", "desc": "Rust fundamentals", "duration": 120, "price": 80}, {"name": "System Design", "desc": "Architecture help", "duration": 90, "price": 70}]},
                {"name": "Alex Code", "email": "alex@tech.edu", "phone": "(555) 456-7802", "avatar": "https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?w=200&auto=format&fit=crop&q=60", "venue": "Alex''s Web Dev Bootcamp", "description": "Full-stack web development.", "cover": "https://images.unsplash.com/photo-1498050108023-c5249f4df085?w=800&auto=format&fit=crop&q=60", "category": "Tech", "bio": "What''s up! I''m Alex, 23 years old and a senior majoring in Computer Science. I''m from San Francisco and I''ve been doing web development for 5 years. I love building full-stack applications and teaching others! When I''m not coding or teaching, I''m building side projects, watching coding tutorials, or going to tech meetups. My favorite movies are The Social Network and Silicon Valley. I''m really into React, Node.js, and modern web development. I also enjoy rock climbing, trying new restaurants, and going to concerts. Web development is fun and creative - let''s build something awesome together!", "services": [{"name": "React Tutorial", "desc": "Learn React", "duration": 120, "price": 70}, {"name": "Node.js Backend", "desc": "Server development", "duration": 120, "price": 70}, {"name": "Database Design", "desc": "SQL and NoSQL", "duration": 90, "price": 60}, {"name": "Deployment Help", "desc": "Deploy to AWS/Vercel", "duration": 60, "price": 50}]},
                {"name": "Sam Debug", "email": "sam@tech.edu", "phone": "(555) 456-7803", "avatar": "https://images.unsplash.com/photo-1500648767791-00dcc994a43e?w=200&auto=format&fit=crop&q=60", "venue": "Sam''s Debugging Service", "description": "Fix your bugs fast.", "cover": "https://images.unsplash.com/photo-1555066931-4365d14bab8c?w=800&auto=format&fit=crop&q=60", "category": "Tech", "bio": "Hey! I''m Sam, 25 years old and a graduate student studying Software Engineering. I''m from Austin, Texas and I''ve been debugging code for 7 years. I love solving puzzles and finding bugs! When I''m not debugging or studying, I''m reading about debugging techniques, contributing to Stack Overflow, or playing puzzle games. My favorite movies are The Imitation Game and The Social Network. I''m really into debugging tools, code analysis, and software quality. I also enjoy chess, reading, and trying new coffee shops. Bugs are just puzzles waiting to be solved. I''ll help you find and fix them quickly!", "services": [{"name": "Bug Fix", "desc": "Quick bug resolution", "duration": 30, "price": 40}, {"name": "Code Audit", "desc": "Find all issues", "duration": 120, "price": 100}, {"name": "Performance Tuning", "desc": "Optimize your code", "duration": 90, "price": 80}, {"name": "Refactoring", "desc": "Clean up codebase", "duration": 180, "price": 150}]},
                {"name": "Jordan Cloud", "email": "jordan@tech.edu", "phone": "(555) 456-7804", "avatar": "https://images.unsplash.com/photo-1534528741775-53994a69daeb?w=200&auto=format&fit=crop&q=60", "venue": "Jordan''s AWS Setup", "description": "Cloud infrastructure help.", "cover": "https://images.unsplash.com/photo-1451187580459-43490279c0fa?w=800&auto=format&fit=crop&q=60", "category": "Tech", "bio": "Hi! I''m Jordan, 26 years old and a graduate student studying Cloud Computing. I''m from Denver, Colorado and I''m AWS certified. I''ve been working with cloud infrastructure for 4 years and I love helping others deploy their applications! When I''m not working with AWS or teaching, I''m studying for certifications, reading cloud blogs, or experimenting with new services. My favorite movies are The Matrix and Inception. I''m really into DevOps, infrastructure as code, and cloud architecture. I also enjoy hiking, photography, and trying new restaurants. Cloud computing is the future - let''s get your apps deployed and scaling!", "services": [{"name": "AWS Setup", "desc": "Initial AWS config", "duration": 120, "price": 100}, {"name": "Docker Deployment", "desc": "Container setup", "duration": 90, "price": 80}, {"name": "CI/CD Pipeline", "desc": "GitHub Actions setup", "duration": 120, "price": 90}, {"name": "Monitoring Setup", "desc": "CloudWatch config", "duration": 60, "price": 60}]},
                {"name": "Morgan Data", "email": "morgan@tech.edu", "phone": "(555) 456-7805", "avatar": "https://images.unsplash.com/photo-1534528741775-53994a69daeb?w=200&auto=format&fit=crop&q=60", "venue": "Morgan''s Data Science", "description": "ML and data analysis.", "cover": "https://images.unsplash.com/photo-1551288049-bebda4e38f71?w=800&auto=format&fit=crop&q=60", "category": "Tech", "bio": "Hey! I''m Morgan, 24 years old and a graduate student studying Data Science. I''m from Boston and I''ve been doing data science for 4 years. I love working with data and building ML models! When I''m not analyzing data or teaching, I''m reading research papers, working on Kaggle competitions, or experimenting with new ML techniques. My favorite movies are The Imitation Game and A Beautiful Mind. I''m really into machine learning, statistics, and data visualization. I also enjoy running, reading, and trying new restaurants. Data tells stories - let''s uncover them together! I''ll help you analyze data and build predictive models.", "services": [{"name": "Python Pandas", "desc": "Data manipulation", "duration": 90, "price": 65}, {"name": "Machine Learning", "desc": "Scikit-learn basics", "duration": 120, "price": 85}, {"name": "Data Visualization", "desc": "Matplotlib/Seaborn", "duration": 90, "price": 60}, {"name": "Jupyter Setup", "desc": "Notebook environment", "duration": 60, "price": 45}]},
                {"name": "Riley Crypto", "email": "riley@tech.edu", "phone": "(555) 456-7806", "avatar": "https://images.unsplash.com/photo-1500648767791-00dcc994a43e?w=200&auto=format&fit=crop&q=60", "venue": "Riley''s Blockchain Dev", "description": "Smart contracts and Web3.", "cover": "https://images.unsplash.com/photo-1639762681485-074b7f938ba0?w=800&auto=format&fit=crop&q=60", "category": "Tech", "bio": "What''s up! I''m Riley, 22 years old and a senior majoring in Computer Science. I''m from Miami and I''ve been into blockchain and crypto for 3 years. I love building decentralized applications and smart contracts! When I''m not coding or teaching, I''m researching DeFi protocols, trading crypto, or contributing to open source projects. My favorite movies are The Matrix and Ready Player One. I''m really into blockchain technology, smart contracts, and Web3. I also enjoy gaming, trying new restaurants, and going to crypto meetups. Blockchain is the future of the internet - let''s build it together!", "services": [{"name": "Solidity Basics", "desc": "Smart contract intro", "duration": 120, "price": 90}, {"name": "DeFi Development", "desc": "DeFi protocols", "duration": 180, "price": 130}, {"name": "NFT Minting", "desc": "Create NFT collection", "duration": 150, "price": 110}, {"name": "Web3 Integration", "desc": "Connect to blockchain", "duration": 90, "price": 75}]},
                {"name": "Quinn Mobile", "email": "quinn@tech.edu", "phone": "(555) 456-7807", "avatar": "https://images.unsplash.com/photo-1472099645785-5658abf4ff4e?w=200&auto=format&fit=crop&q=60", "venue": "Quinn''s Mobile App Dev", "description": "iOS and Android apps.", "cover": "https://images.unsplash.com/photo-1512941937669-90a1b58e7e9c?w=800&auto=format&fit=crop&q=60", "category": "Tech", "bio": "Hey! I''m Quinn, 23 years old and a senior majoring in Mobile Development. I''m from Portland, Oregon and I''ve been building mobile apps for 4 years. I love creating apps that people use every day! When I''m not coding or teaching, I''m building side projects, testing new apps, or going to mobile dev meetups. My favorite movies are The Social Network and Her. I''m really into iOS development, React Native, and mobile UX. I also enjoy hiking, photography, and trying new apps. Mobile apps are everywhere - let''s build something people will love!", "services": [{"name": "React Native", "desc": "Cross-platform apps", "duration": 180, "price": 120}, {"name": "Swift iOS", "desc": "Native iOS dev", "duration": 150, "price": 100}, {"name": "Kotlin Android", "desc": "Native Android", "duration": 150, "price": 100}, {"name": "App Store Setup", "desc": "Publishing help", "duration": 90, "price": 70}]},
                {"name": "Skyler Security", "email": "skyler@tech.edu", "phone": "(555) 456-7808", "avatar": "https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?w=200&auto=format&fit=crop&q=60", "venue": "Skyler''s Cybersecurity", "description": "Pen testing and security audits.", "cover": "https://images.unsplash.com/photo-1550751827-4bd374c3f58b?w=800&auto=format&fit=crop&q=60", "category": "Tech", "bio": "Hey! I''m Skyler, 27 years old and a graduate student studying Cybersecurity. I''m from Washington D.C. and I''m a certified ethical hacker. I''ve been doing security work for 5 years and I love finding vulnerabilities! When I''m not hacking or teaching, I''m doing CTF competitions, reading security blogs, or practicing on HackTheBox. My favorite movies are The Matrix and Hackers. I''m really into penetration testing, cryptography, and security research. I also enjoy gaming, reading, and trying new restaurants. Security is critical - let''s make your applications secure! I''ll help you find vulnerabilities and fix them.", "services": [{"name": "Security Audit", "desc": "Find vulnerabilities", "duration": 180, "price": 200}, {"name": "Pen Testing", "desc": "Ethical hacking", "duration": 240, "price": 250}, {"name": "Encryption Setup", "desc": "Secure your data", "duration": 90, "price": 100}, {"name": "Security Training", "desc": "Learn security", "duration": 120, "price": 120}]},
