                {"name": "Pizza & Code", "email": "pizzacode@tech.edu", "phone": "(555) 456-7818", "avatar": "https://images.unsplash.com/photo-1513104890138-7c749659a591?w=200&auto=format&fit=crop&q=60", "venue": "Pizza & Code", "description": "Pizza delivery for late night coding sessions.", "cover": "https://images.unsplash.com/photo-1574071318508-1cdbab80d002?w=800&auto=format&fit=crop&q=60", "category": "Food", "bio": "Hey! I''m the owner of Pizza & Code. I''m 29 years old and from New York City. I''m a licensed food service operator - not a student! I opened this pizza place 3 years ago specifically for late-night coders. When I''m not making pizza, I''m trying new pizza recipes, watching cooking shows, or going to tech events. My favorite movies are The Godfather and Goodfellas. I''m really into pizza, tech culture, and late-night food. I also enjoy gaming, trying new restaurants, and going to hackathons. We deliver fast, hot pizza perfect for late-night coding sessions. Order up!", "services": [{"name": "Pizza Delivery", "desc": "Fast delivery to dorms", "duration": 30, "price": 3}, {"name": "Hackathon Package", "desc": "Pizza for hackathons", "duration": 45, "price": 80}, {"name": "Bulk Order", "desc": "Large orders for events", "duration": 60, "price": 120}, {"name": "Pickup Order", "desc": "Order ahead", "duration": 15, "price": 0}]},
                {"name": "The Lab Cafe", "email": "labcafe@tech.edu", "phone": "(555) 456-7819", "avatar": "https://images.unsplash.com/photo-1509042239860-f550ce710b93?w=200&auto=format&fit=crop&q=60", "venue": "The Lab Cafe", "description": "Cafe in the CS building. Perfect for study groups.", "cover": "https://images.unsplash.com/photo-1495474472287-4d71bcdd2085?w=800&auto=format&fit=crop&q=60", "category": "Food", "bio": "Hi! I''m the manager of The Lab Cafe. I''m 31 years old and from Portland, Oregon. I''m a licensed cafe manager - not a student! I''ve been managing cafes for 8 years and I love creating spaces for students. When I''m not at the cafe, I''m sourcing coffee, developing new menu items, or reading about coffee. My favorite movies are The Social Network and The Imitation Game. I''m really into coffee, student life, and creating study-friendly environments. I also enjoy reading, trying new restaurants, and going to coffee events. We''re located right in the CS building - perfect for study groups and coding sessions. Come study and fuel up!", "services": [{"name": "Study Group Package", "desc": "Coffee + snacks", "duration": 60, "price": 45}, {"name": "Table Reservation", "desc": "Reserve study space", "duration": 120, "price": 0}, {"name": "Event Catering", "desc": "Catering for CS events", "duration": 120, "price": 180}, {"name": "Private Room", "desc": "Reserve private room", "duration": 180, "price": 100}]},
                {"name": "Meal Prep Tech", "email": "mealpreptech@tech.edu", "phone": "(555) 456-7820", "avatar": "https://images.unsplash.com/photo-1546069901-ba9599a7e63c?w=200&auto=format&fit=crop&q=60", "venue": "Meal Prep Tech", "description": "Meal prep for busy CS students. Healthy and quick.", "cover": "https://images.unsplash.com/photo-1504674900247-0877df9cc836?w=800&auto=format&fit=crop&q=60", "category": "Food", "bio": "Hi! I''m the owner of Meal Prep Tech. I''m 33 years old and from Los Angeles. I''m a licensed food service operator and certified nutritionist - not a student! I started this business 3 years ago to help busy CS students eat healthy. When I''m not prepping meals, I''m developing recipes, sourcing ingredients, or working out. My favorite movies are Chef and The Pursuit of Happyness. I''m really into nutrition, meal planning, and helping students. I also enjoy fitness, reading nutrition research, and going to farmers markets. We prep healthy meals perfect for busy CS students. Eat well, code better!", "services": [{"name": "Weekly Meal Prep", "desc": "5 meals for the week", "duration": 60, "price": 55}, {"name": "Bulk Order", "desc": "Meal prep for groups", "duration": 120, "price": 250}, {"name": "Custom Plan", "desc": "Personalized meal plan", "duration": 90, "price": 80}, {"name": "Nutrition Consult", "desc": "Nutrition consultation", "duration": 45, "price": 35}]},
                {"name": "The Debug Bar", "email": "debugbar@tech.edu", "phone": "(555) 456-7821", "avatar": "https://images.unsplash.com/photo-1514933651103-005eec06c04b?w=200&auto=format&fit=crop&q=60", "venue": "The Debug Bar", "description": "Bar for CS students. 21+ only. Open late.", "cover": "https://images.unsplash.com/photo-1470337458703-46ad1756a187?w=800&auto=format&fit=crop&q=60", "category": "Food", "bio": "Hey! I''m the owner of The Debug Bar. I''m 35 years old and from Austin, Texas. I''m a licensed bar owner and former software engineer - not a student! I opened this bar 5 years ago specifically for CS students. When I''m not running the bar, I''m mixing cocktails, watching tech documentaries, or going to tech events. My favorite movies are The Social Network and The Matrix. I''m really into craft cocktails, tech culture, and creating spaces for developers. I also enjoy gaming, trying new restaurants, and going to tech meetups. We serve craft cocktails in a tech-themed atmosphere. Perfect for unwinding after a long coding session. 21+ only!", "services": [{"name": "Table Reservation", "desc": "Reserve a table", "duration": 120, "price": 0}, {"name": "Private Event", "desc": "Reserve for events", "duration": 240, "price": 300}, {"name": "Bar Rental", "desc": "Full bar rental", "duration": 360, "price": 600}, {"name": "Catering", "desc": "Food and drinks", "duration": 180, "price": 250}]}
            ]
        }
    ]'::jsonb;

BEGIN
    -- Clean Slate: Delete test/seed data only
    -- IMPORTANT: We preserve real user accounts (non-test emails)
    
    -- First, delete availability for venues owned by test users
    DELETE FROM public.availability WHERE venue_id IN (
        SELECT v.id FROM public.venues v
        JOIN public.users u ON v.owner_id = u.id
        WHERE u.email LIKE '%@state.edu' 
           OR u.email LIKE '%@ivy.edu' 
           OR u.email LIKE '%@tech.edu'
    );
    
    -- Delete reviews for bookings made by test users or for test venues
    DELETE FROM public.reviews WHERE booking_id IN (
        SELECT b.id FROM public.bookings b
        JOIN public.users u ON b.user_id = u.id
        WHERE u.email LIKE '%@state.edu' 
           OR u.email LIKE '%@ivy.edu' 
           OR u.email LIKE '%@tech.edu'
    );
    
    -- Delete bookings made by test users
    DELETE FROM public.bookings WHERE user_id IN (
        SELECT id FROM public.users 
        WHERE email LIKE '%@state.edu' 
           OR email LIKE '%@ivy.edu' 
           OR email LIKE '%@tech.edu'
    );
    
    -- Delete services for venues owned by test users
    DELETE FROM public.services WHERE venue_id IN (
        SELECT v.id FROM public.venues v
        JOIN public.users u ON v.owner_id = u.id
        WHERE u.email LIKE '%@state.edu' 
           OR u.email LIKE '%@ivy.edu' 
           OR u.email LIKE '%@tech.edu'
    );
    
    -- Delete venues owned by test users
    DELETE FROM public.venues WHERE owner_id IN (
        SELECT id FROM public.users 
        WHERE email LIKE '%@state.edu' 
           OR email LIKE '%@ivy.edu' 
           OR email LIKE '%@tech.edu'
    );
    
    -- Delete test users from public.users (this will cascade to auth.users via ON DELETE CASCADE)
    DELETE FROM public.users 
    WHERE email LIKE '%@state.edu' 
       OR email LIKE '%@ivy.edu' 
       OR email LIKE '%@tech.edu';
    
    -- Delete test users from auth.users (in case they weren't cascaded)
    DELETE FROM auth.users 
    WHERE email LIKE '%@state.edu' 
       OR email LIKE '%@ivy.edu' 
       OR email LIKE '%@tech.edu';

    -- Loop through each campus
    FOR campus_data IN SELECT value FROM jsonb_array_elements(providers_data)
    LOOP
        -- Loop through each provider in the campus
        FOR provider_json IN SELECT value FROM jsonb_array_elements(campus_data->'providers')
        LOOP
            -- Generate new IDs for user and venue
            new_user_id := uuid_generate_v4();
            new_venue_id := uuid_generate_v4();

            -- Insert into auth.users (Supabase auth table)
            INSERT INTO auth.users (id, email, raw_user_meta_data, created_at)
            VALUES (
                new_user_id,
                provider_json->>'email',
                json_build_object(
                    'full_name', provider_json->>'name',
                    'avatar_url', provider_json->>'avatar'
                ),
                NOW()
            );

            -- Insert user bio into public.users
            INSERT INTO public.users (id, email, name, avatar_url, bio, role)
            VALUES (
                new_user_id,
                provider_json->>'email',
                provider_json->>'name',
                provider_json->>'avatar',
                provider_json->>'bio',
                'venue_owner'
            )
            ON CONFLICT (id) DO UPDATE SET bio = EXCLUDED.bio;

            -- Insert venue with approved status for testing, including provider contact info
            INSERT INTO public.venues (id, owner_id, name, description, campus, image_url, category, status, provider_name, provider_email, provider_phone)
            VALUES (
                new_venue_id,
                new_user_id,
                provider_json->>'venue',
                provider_json->>'description',
                campus_data->>'campus',
                provider_json->>'cover',
                provider_json->>'category',
                'approved',
                provider_json->>'name',
                provider_json->>'email',
                provider_json->>'phone'
            );

            -- Insert services for this venue
            FOR service_json IN SELECT value FROM jsonb_array_elements(provider_json->'services')
            LOOP
                INSERT INTO public.services (venue_id, name, description, duration, price)
                VALUES (
                    new_venue_id,
                    service_json->>'name',
                    service_json->>'desc',
                    (service_json->>'duration')::int,
                    (service_json->>'price')::numeric
                );
            END LOOP;

            -- Insert availability for this venue (Monday-Saturday, 9am-6pm)
            -- day_of_week: 0=Sunday, 1=Monday, 2=Tuesday, 3=Wednesday, 4=Thursday, 5=Friday, 6=Saturday
            FOR day_num IN 1..6 LOOP
                INSERT INTO public.availability (venue_id, day_of_week, start_time, end_time)
                VALUES (
                    new_venue_id,
                    day_num,
                    '09:00:00'::TIME,
                    '18:00:00'::TIME
                );
            END LOOP;

            -- Add Sunday availability for some venues (Food category stays open)
            IF (provider_json->>'category') = 'Food' THEN
                INSERT INTO public.availability (venue_id, day_of_week, start_time, end_time)
                VALUES (
                    new_venue_id,
                    0, -- Sunday
                    '10:00:00'::TIME,
                    '20:00:00'::TIME
                );
            END IF;

        END LOOP;
    END LOOP;

END $$;
